//! R2-3b acceptance: `build_plan_v1` against the TS production pipeline.
//!
//! Two layers:
//! 1. FROZEN CORPUS — one JSON per parity case (generated by
//!    `rust-parity-inputs.test.ts` from the TS pipeline: importer →
//!    projectScoreDocumentV1 → buildPlaybackPlan → hand filter → atoms /
//!    scoreEvents / canonical projection). The Rust plan must equal the TS
//!    candidate FIELD BY FIELD (occurrences, groups, atoms, scoreEvents,
//!    runtimeIds), and the a3 fingerprint gate over the Rust plan must
//!    reproduce the TS gate's fingerprint (or its exact error code on the
//!    blocked case).
//! 2. SEMANTIC negatives/positives over hand-built minimal ScoreDocumentV1
//!    instances (playback-planner.ts rules: range, tie, same-onset grouping,
//!    loop passes, hand filter, tick grid, report binding).

use rhythm_core::contract_v1::document::compute_score_revision_id;
use rhythm_core::contract_v1::{
    build_plan_v1, plan_fingerprint_v1_gate, validate_score_document_v1,
};
use serde_json::{json, Value};

const CORPUS_DIR: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../../audit-r1/fixtures/parity-cases/rust-parity-input"
);

fn corpus_files() -> Vec<std::path::PathBuf> {
    let mut files: Vec<std::path::PathBuf> = std::fs::read_dir(CORPUS_DIR)
        .expect("read rust-parity-input corpus directory")
        .filter_map(|entry| entry.ok())
        .map(|entry| entry.path())
        .filter(|path| path.extension().map(|ext| ext == "json").unwrap_or(false))
        .collect();
    files.sort();
    files
}

/// Projects the PlannerOutput onto the ParityCandidate shape: occurrences
/// drop the runtime keys (occurrenceId/scoreEventId live in runtimeIds and
/// scoreEvents.runtimeOccurrenceId) and groups drop the member id lists
/// (TS CanonicalGroup carries locators only); everything else compares as-is.
fn project_plan_to_candidate(plan: &Value) -> Value {
    let strip = |value: &Value, keys: &[&str]| {
        let mut object = value.clone();
        if let Some(map) = object.as_object_mut() {
            for key in keys {
                map.remove(*key);
            }
        }
        object
    };
    json!({
        "occurrences": plan["occurrences"].as_array().expect("occurrences array")
            .iter().map(|occurrence| strip(occurrence, &["occurrenceId", "scoreEventId"])).collect::<Vec<_>>(),
        "groups": plan["groups"].as_array().expect("groups array")
            .iter().map(|group| strip(group, &["occurrenceIds", "scoreEventIds"])).collect::<Vec<_>>(),
        "atoms": plan["atoms"].clone(),
        "scoreEvents": plan["scoreEvents"].clone(),
        "runtimeIds": plan["runtimeIds"].clone(),
    })
}

fn assert_section_eq(case_id: &str, section: &str, expected: &Value, actual: &Value) {
    match (expected.as_array(), actual.as_array()) {
        (Some(expected_list), Some(actual_list)) => {
            assert_eq!(
                actual_list.len(),
                expected_list.len(),
                "{case_id}: {section} length {} != expected {}",
                actual_list.len(),
                expected_list.len()
            );
            for (index, (want, got)) in expected_list.iter().zip(actual_list).enumerate() {
                assert_eq!(got, want, "{case_id}: {section}[{index}] mismatch\nexpected: {want}\nactual:   {got}");
            }
        }
        _ => assert_eq!(actual, expected, "{case_id}: {section} mismatch"),
    }
}

#[test]
fn frozen_corpus_matches_the_ts_pipeline_field_by_field() {
    let files = corpus_files();
    assert_eq!(files.len(), 15, "the frozen corpus must carry all 15 parity cases");
    for path in &files {
        let record: Value = serde_json::from_str(
            &std::fs::read_to_string(path).expect("read corpus record"),
        )
        .expect("corpus record parses");
        let case_id = record["caseId"].as_str().expect("caseId").to_string();
        let document = &record["document"];
        let report = &record["report"];
        let config = &record["config"];
        let expected = &record["expectedCandidate"];
        let meta = &record["meta"];

        // The frozen V1 input must satisfy the a3 validator (pins the corpus
        // to the frozen schema — a projection drift cannot hide here).
        let issues = validate_score_document_v1(document);
        assert!(issues.is_empty(), "{case_id}: corpus document must be clean: {issues:?}");

        // THE planner call under test.
        let plan = build_plan_v1(document, report, config)
            .unwrap_or_else(|error| panic!("{case_id}: build_plan_v1 failed: {} ({})", error.code, error));
        let candidate = project_plan_to_candidate(&plan);
        // atoms[].beat is a DISPLAY field (R2-1 §3.3): the authoritative
        // diffCandidates records its differences as serialization-only and
        // never a truth source — serde_json's float parsing can differ by one
        // ulp from the JS-written text, so the structural fields carry the
        // assertion and beat gets a display-tolerance check instead.
        assert_section_eq(&case_id, "occurrences", &expected["occurrences"], &candidate["occurrences"]);
        assert_section_eq(&case_id, "groups", &expected["groups"], &candidate["groups"]);
        assert_section_eq(&case_id, "scoreEvents", &expected["scoreEvents"], &candidate["scoreEvents"]);
        assert_section_eq(&case_id, "runtimeIds", &expected["runtimeIds"], &candidate["runtimeIds"]);
        let expected_atoms = expected["atoms"].as_array().expect("expected atoms");
        let actual_atoms = candidate["atoms"].as_array().expect("atoms");
        assert_eq!(actual_atoms.len(), expected_atoms.len(), "{case_id}: atoms length");
        for (index, (want, got)) in expected_atoms.iter().zip(actual_atoms).enumerate() {
            let strip_beat = |atom: &Value| {
                let mut object = atom.clone();
                object.as_object_mut().map(|map| map.remove("beat")).expect("atom object");
                object
            };
            assert_eq!(strip_beat(got), strip_beat(want), "{case_id}: atoms[{index}] mismatch");
            let want_beat = want["beat"].as_f64().expect("beat number");
            let got_beat = got["beat"].as_f64().expect("beat number");
            assert!((want_beat - got_beat).abs() < 1e-9,
                "{case_id}: atoms[{index}].beat display drift: {got_beat} vs {want_beat}");
        }

        // Planner-domain metadata: issues, scope codes, hand-filter misses,
        // atom blockers, strict flag.
        assert_eq!(plan["planStrictAllowed"], meta["planStrictAllowed"], "{case_id}: planStrictAllowed");
        assert_eq!(plan["planIssues"], meta["planIssues"], "{case_id}: planIssues");
        assert_eq!(plan["scopeCodes"], meta["scopeCodes"], "{case_id}: scopeCodes");
        assert_eq!(plan["missingEventIds"], meta["missingEventIds"], "{case_id}: missingEventIds");
        assert_eq!(plan["atomIssueCodes"], meta["atomIssueCodes"], "{case_id}: atomIssueCodes");

        // L1: the a3 gate over the RUST plan must reproduce the TS gate's
        // fingerprint byte-for-byte — or its exact error code when blocked.
        let ts_fingerprint = meta["fingerprint"].as_str();
        let ts_error = meta["fingerprintErrorCode"].as_str();
        match plan_fingerprint_v1_gate(document, report, &plan, config) {
            Ok(fingerprint) => {
                assert_eq!(
                    Some(fingerprint.as_str()),
                    ts_fingerprint,
                    "{case_id}: Rust gate fingerprint must equal the TS gate fingerprint"
                );
                assert!(ts_error.is_none(), "{case_id}: TS reported an error but Rust passed");
            }
            Err(error) => {
                assert_eq!(
                    ts_error,
                    Some(error.code.as_str()),
                    "{case_id}: gate error code must match the TS gate rejection"
                );
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Semantic negatives/positives over minimal hand-built ScoreDocumentV1 values.
// ---------------------------------------------------------------------------

const FP: &str = "1111111111111111111111111111111111111111111111111111111111111111";

fn note_event(
    id: &str,
    measure: i64,
    source_ordinal: i64,
    onset: &str,
    duration: &str,
    staff: i64,
    voice: &str,
    midi: i64,
    spelling: &str,
) -> Value {
    let rational = |text: &str| {
        let (n, d) = text.split_once('/').unwrap();
        json!({ "numerator": n.parse::<i64>().unwrap(), "denominator": d.parse::<i64>().unwrap() })
    };
    json!({
        "eventId": id,
        "kind": "note",
        "source": {
            "partId": "P1", "measureOrdinal": measure,
            "staffNumber": staff, "sourceOrdinal": source_ordinal, "voiceId": voice,
        },
        "onsetBeat": rational(onset),
        "durationBeat": rational(duration),
        "dots": 0,
        "pitch": {
            "step": spelling.chars().next().unwrap().to_string(),
            "alter": { "numerator": 0, "denominator": 1 },
            "octave": 4,
            "midiNote": midi,
            "spelling": spelling,
        },
        "tieStart": false, "tieStop": false, "tiedStart": false, "tiedStop": false,
        "isGrace": false, "isCue": false,
        "articulations": [],
    })
}

fn measure(ordinal: i64, start: &str, duration: &str, events: Value) -> Value {
    let rational = |text: &str| {
        let (n, d) = text.split_once('/').unwrap();
        json!({ "numerator": n.parse::<i64>().unwrap(), "denominator": d.parse::<i64>().unwrap() })
    };
    json!({
        "ordinal": ordinal,
        "implicit": false,
        "startBeat": rational(start),
        "durationBeat": rational(duration),
        "printedNumber": ordinal.to_string(),
        "attributes": {
            "divisions": 1,
            "time": { "beats": 4, "beatType": 4 },
            "key": { "fifths": 0, "mode": "major" },
            "staves": 2,
            "clefs": [
                { "staffNumber": 1, "sign": "G", "line": 2 },
                { "staffNumber": 2, "sign": "F", "line": 4 },
            ],
        },
        "events": events,
        "barlines": [],
        "capabilities": [],
    })
}

fn minimal_document(events: Value) -> Value {
    let source_fingerprint = format!("sha256:{FP}");
    json!({
        "schemaVersion": 1,
        "normalizerVersion": "normalizer-1",
        "supportProfileVersion": "musicxml-v1.0",
        "scoreRevisionId": compute_score_revision_id(&source_fingerprint, "normalizer-1"),
        "source": { "format": "musicxml-partwise", "sourceFingerprint": source_fingerprint },
        "metadata": { "workTitle": "T", "composer": "C" },
        "parts": [{
            "partId": "P1", "name": "Piano", "staves": 2,
            "measures": [
                measure(1, "0/1", "4/1", events),
            ],
        }],
        "tieSpans": [],
        "tempoMarks": [],
        "capabilities": [],
    })
}

fn minimal_report() -> Value {
    json!({ "fingerprint": FP, "strictAllowed": true, "capabilities": [] })
}

fn config_for(hand: &str, start: i64, end: i64, repeat: Value, count_in_us: i64) -> Value {
    json!({
        "partId": "P1",
        "range": { "startMeasureOrdinal": start, "endMeasureOrdinal": end },
        "repeatSelection": repeat,
        "hand": hand,
        "handMapping": { "schemaVersion": 1, "mappingVersion": "hand-mapping-1", "source": "user",
            "parts": [{ "partId": "P1", "staves": [
                { "staffNumber": 1, "hand": "right" },
                { "staffNumber": 2, "hand": "left" },
            ] }] },
        "bpm": { "numerator": 80, "denominator": 1 },
        "ticksPerQuarter": 960,
        "countInUs": count_in_us,
        "unsupportedNotationPolicy": "reject-strict",
        "plannerVersion": "parity-harness-1",
    })
}

fn base_config() -> Value {
    config_for("both", 1, 1, json!({ "kind": "none" }), 3_000_000)
}

#[test]
fn invalid_range_is_rejected_before_any_plan() {
    let document = minimal_document(json!([note_event("e1", 1, 1, "0/1", "1/1", 1, "1", 60, "C4")]));

    // end beyond the score's measure count.
    let error = build_plan_v1(&document, &minimal_report(), &config_for("both", 1, 2, json!({ "kind": "none" }), 0))
        .expect_err("end > measure count must fail");
    assert_eq!(error.code, "INVALID_RANGE");

    // start below 1.
    let error = build_plan_v1(&document, &minimal_report(), &config_for("both", 0, 1, json!({ "kind": "none" }), 0))
        .expect_err("start < 1 must fail");
    assert_eq!(error.code, "INVALID_RANGE");

    // An empty parts array means zero measures.
    let mut empty = minimal_document(json!([]));
    empty["parts"] = Value::Array(vec![]);
    let error = build_plan_v1(&empty, &minimal_report(), &base_config())
        .expect_err("no measures must fail");
    assert_eq!(error.code, "INVALID_RANGE");
}

#[test]
fn invalid_document_or_report_never_yields_a_plan() {
    let events = json!([note_event("e1", 1, 1, "0/1", "1/1", 1, "1", 60, "C4")]);

    // Tampered document (non-reduced rational) is rejected by the a3 layer.
    let mut tampered = minimal_document(events.clone());
    tampered["parts"][0]["measures"][0]["startBeat"] = json!({ "numerator": 2, "denominator": 4 });
    let error = build_plan_v1(&tampered, &minimal_report(), &base_config())
        .expect_err("invalid document must fail");
    assert_eq!(error.code, "DOCUMENT_VALIDATION_FAILED");

    // The C-12 binding: report fingerprint must equal the document's own
    // source fingerprint (bare 64 hex on both sides).
    let mut foreign = minimal_report();
    foreign["fingerprint"] = Value::String("2".repeat(64));
    let error = build_plan_v1(&minimal_document(events.clone()), &foreign, &base_config())
        .expect_err("report mismatch must fail");
    assert_eq!(error.code, "DOCUMENT_REPORT_MISMATCH");

    // strictAllowed must be an explicit boolean — never defaulted.
    let mut no_flag = minimal_report();
    no_flag.as_object_mut().unwrap().remove("strictAllowed");
    let error = build_plan_v1(&minimal_document(events.clone()), &no_flag, &base_config())
        .expect_err("missing strictAllowed must fail");
    assert_eq!(error.code, "INVALID_REPORT");

    // strictAllowed=false keeps the plan but blocks strict.
    let mut not_strict = minimal_report();
    not_strict["strictAllowed"] = Value::Bool(false);
    let plan = build_plan_v1(&minimal_document(events), &not_strict, &base_config())
        .expect("non-strict plan still builds");
    assert_eq!(plan["planStrictAllowed"], Value::Bool(false));
    assert_eq!(
        plan["planIssues"].as_array().expect("issues")[0]["code"],
        Value::String("score_not_strict_ready".into())
    );
}

#[test]
fn tie_spans_stretch_the_onset_and_skip_continuations() {
    let events = json!([
        { "eventId": "t1", "kind": "note",
          "source": { "partId": "P1", "measureOrdinal": 1, "staffNumber": 1, "sourceOrdinal": 1, "voiceId": "1" },
          "onsetBeat": { "numerator": 0, "denominator": 1 },
          "durationBeat": { "numerator": 1, "denominator": 1 },
          "dots": 0,
          "pitch": { "step": "C", "alter": { "numerator": 0, "denominator": 1 }, "octave": 4,
                     "midiNote": 60, "spelling": "C4" },
          "tieStart": true, "tieStop": false, "tiedStart": true, "tiedStop": false,
          "tieSpanId": "tie:1",
          "isGrace": false, "isCue": false, "articulations": [] },
        { "eventId": "t2", "kind": "note",
          "source": { "partId": "P1", "measureOrdinal": 1, "staffNumber": 1, "sourceOrdinal": 2, "voiceId": "1" },
          "onsetBeat": { "numerator": 1, "denominator": 1 },
          "durationBeat": { "numerator": 1, "denominator": 1 },
          "dots": 0,
          "pitch": { "step": "C", "alter": { "numerator": 0, "denominator": 1 }, "octave": 4,
                     "midiNote": 60, "spelling": "C4" },
          "tieStart": false, "tieStop": true, "tiedStart": false, "tiedStop": true,
          "tieSpanId": "tie:1",
          "isGrace": false, "isCue": false, "articulations": [] },
    ]);
    let mut document = minimal_document(events);
    document["tieSpans"] = json!([
        { "id": "tie:1", "pitchKey": "60:1", "eventIds": ["t1", "t2"],
          "startBeat": { "numerator": 0, "denominator": 1 },
          "endBeat": { "numerator": 2, "denominator": 1 } }
    ]);

    let plan = build_plan_v1(&document, &minimal_report(), &base_config()).expect("tie plan builds");
    let occurrences = plan["occurrences"].as_array().expect("occurrences");
    // The continuation emits NO occurrence; the onset stretches to the span end.
    assert_eq!(occurrences.len(), 1, "tie continuation must not produce an occurrence");
    assert_eq!(occurrences[0]["scoreEventId"], Value::String("t1".into()));
    assert_eq!(occurrences[0]["durationBeat"], Value::String("2/1".into()),
        "tie onset duration = span.endBeat - onset");
    assert_eq!(occurrences[0]["isTieOnset"], Value::Bool(true));

    // The stretched duration also drives the group and the µs conversion.
    assert_eq!(plan["groups"][0]["durationBeat"], Value::String("2/1".into()));
    assert_eq!(plan["scoreEvents"][0]["targetDurationUs"], Value::from(1_500_000), // 2 beats @80BPM
        "per-note scoreEvents carry the stretched duration");
}

#[test]
fn same_onset_notes_share_one_group_with_the_longest_duration() {
    let events = json!([
        note_event("c1", 1, 1, "0/1", "1/1", 1, "1", 60, "C4"),
        note_event("c2", 1, 2, "0/1", "2/1", 2, "2", 64, "E4"),
    ]);
    let plan = build_plan_v1(&minimal_document(events), &minimal_report(), &base_config())
        .expect("chord plan builds");

    let groups = plan["groups"].as_array().expect("groups");
    assert_eq!(groups.len(), 1, "same-onset notes group together (chord grouping)");
    assert_eq!(groups[0]["durationBeat"], Value::String("2/1".into()),
        "group duration = longest member");
    assert_eq!(groups[0]["pitches"], json!(["C4", "E4"]));
    assert_eq!(groups[0]["staffNumbers"], json!([1, 2]), "staff numbers deduped and sorted");
    assert_eq!(groups[0]["voiceIds"], json!(["1", "2"]));
    assert_eq!(groups[0]["members"].as_array().map(Vec::len), Some(2));

    // Per-note scoreEvents granularity: TWO events for one group.
    let score_events = plan["scoreEvents"].as_array().expect("scoreEvents");
    assert_eq!(score_events.len(), 2);
    assert_eq!(score_events[0]["targetDurationUs"], Value::from(750_000));
    assert_eq!(score_events[1]["targetDurationUs"], Value::from(1_500_000));
    assert_eq!(score_events[0]["partId"], Value::String("staff-1:voice-1".into()));
    assert_eq!(score_events[1]["partId"], Value::String("staff-2:voice-2".into()));
}

#[test]
fn loop_passes_offset_beats_and_stay_ordered() {
    let events = json!([note_event("e1", 1, 1, "0/1", "1/1", 1, "1", 60, "C4")]);
    let config = config_for("both", 1, 1, json!({ "kind": "range-loop", "count": 2 }), 3_000_000);
    let plan = build_plan_v1(&minimal_document(events), &minimal_report(), &config)
        .expect("loop plan builds");

    let occurrences = plan["occurrences"].as_array().expect("occurrences");
    assert_eq!(occurrences.len(), 2, "one occurrence per loop pass");
    assert_eq!(occurrences[0]["passIndex"], Value::from(0));
    assert_eq!(occurrences[0]["playbackBeat"], Value::String("0/1".into()));
    assert_eq!(occurrences[1]["passIndex"], Value::from(1));
    assert_eq!(occurrences[1]["playbackBeat"], Value::String("4/1".into()),
        "pass 1 playbackBeat = base + rangeDuration (4/1 measure)");
    assert_eq!(occurrences[1]["playbackIndex"], Value::from(1));

    // Same notated event in both passes: scoreEventId equal, occurrence unique.
    assert_eq!(occurrences[0]["scoreEventId"], occurrences[1]["scoreEventId"]);
    assert_ne!(occurrences[0]["occurrenceId"], occurrences[1]["occurrenceId"]);

    // The second pass onset µs: count-in + 4 beats + 0 beats @80BPM.
    let score_events = plan["scoreEvents"].as_array().expect("scoreEvents");
    assert_eq!(score_events[0]["targetOnsetUs"], Value::from(3_000_000));
    assert_eq!(score_events[1]["targetOnsetUs"], Value::from(6_000_000));
}

#[test]
fn hand_filter_keeps_indices_and_drops_empty_groups() {
    // Two same-onset notes on different staves: staff 1 = right, staff 2 = left.
    let events = json!([
        note_event("r1", 1, 1, "0/1", "1/1", 1, "1", 60, "C4"),
        note_event("l1", 1, 2, "0/1", "2/1", 2, "2", 52, "E3"),
    ]);
    let document = minimal_document(events);
    let both_plan = build_plan_v1(&document, &minimal_report(),
        &config_for("both", 1, 1, json!({ "kind": "none" }), 3_000_000))
        .expect("both plan builds");
    // The survivor's ORIGINAL playback index in the unfiltered plan —
    // ordering is (playbackBeat, passIndex, bar, occurrenceId).
    let original_index = both_plan["occurrences"].as_array().expect("occurrences")
        .iter()
        .position(|occurrence| occurrence["scoreEventId"] == Value::String("l1".into()))
        .expect("l1 in the both plan") as i64;

    let config = config_for("left", 1, 1, json!({ "kind": "none" }), 3_000_000);
    let plan = build_plan_v1(&document, &minimal_report(), &config).expect("left-hand plan builds");

    let occurrences = plan["occurrences"].as_array().expect("occurrences");
    assert_eq!(occurrences.len(), 1, "only the left-hand occurrence survives");
    assert_eq!(occurrences[0]["scoreEventId"], Value::String("l1".into()));
    // Original playbackIndex is KEPT (not renumbered after the filter).
    assert_eq!(occurrences[0]["playbackIndex"], Value::from(original_index));

    // The group is recomputed from the survivor (duration = selected longest).
    let groups = plan["groups"].as_array().expect("groups");
    assert_eq!(groups.len(), 1, "the group keeps its survivors");
    assert_eq!(groups[0]["durationBeat"], Value::String("2/1".into()));
    assert_eq!(groups[0]["staffNumbers"], json!([2]));
    assert_eq!(groups[0]["voiceIds"], json!(["2"]));
    assert_eq!(groups[0]["members"].as_array().map(Vec::len), Some(1));

    // planId gains the hand scope; occurrenceId prefix does NOT change.
    assert!(plan["runtimeIds"]["planId"].as_str().unwrap().ends_with(":hand=left"));
    assert!(!occurrences[0]["occurrenceId"].as_str().unwrap().contains("hand"));

    // atoms follow the filtered groups.
    assert_eq!(plan["atoms"].as_array().map(Vec::len), Some(1));
    assert_eq!(plan["atoms"][0]["durationTicks"], Value::from(1920)); // 2 beats * 960
}

#[test]
fn runtime_ids_follow_the_repeat_kind_not_the_pass_count() {
    // Review blocking case: TS branches the planId on repeatSelection.KIND
    // (playback-planner.ts :107-113), so a LEGAL range-loop count of 1 must
    // read `loop1` — never `once`. The ID propagates into occurrenceIds and
    // groupIds, so this is a runtime-identity difference, not cosmetic.
    let events = json!([note_event("e1", 1, 1, "0/1", "1/1", 1, "1", 60, "C4")]);
    let document = minimal_document(events);

    // kind "none" -> the `once` segment.
    let none_plan = build_plan_v1(&document, &minimal_report(),
        &config_for("both", 1, 1, json!({ "kind": "none" }), 3_000_000))
        .expect("none plan builds");
    let none_plan_id = none_plan["runtimeIds"]["planId"].as_str().expect("planId");
    assert!(none_plan_id.contains(":once:"), "kind none must read once: {none_plan_id}");

    // kind "range-loop" count 1 -> the `loop1` segment.
    let loop_one = build_plan_v1(&document, &minimal_report(),
        &config_for("both", 1, 1, json!({ "kind": "range-loop", "count": 1 }), 3_000_000))
        .expect("range-loop x1 plan builds");
    let loop_plan_id = loop_one["runtimeIds"]["planId"].as_str().expect("planId");
    assert!(loop_plan_id.contains(":loop1:"), "range-loop x1 must read loop1: {loop_plan_id}");
    assert_ne!(none_plan_id, loop_plan_id, "the two configs must never share a planId");

    // The planId propagates into EVERY runtime ID of the loop plan.
    let occurrences = loop_one["occurrences"].as_array().expect("occurrences");
    assert_eq!(occurrences.len(), 1, "count=1 still yields exactly one pass");
    assert_eq!(occurrences[0]["passIndex"], Value::from(0));
    let expected_occurrence_id = format!("{loop_plan_id}:p0:e1");
    assert_eq!(occurrences[0]["occurrenceId"], Value::String(expected_occurrence_id.clone()),
        "occurrenceId embeds the loop1 planId");
    assert_eq!(loop_one["runtimeIds"]["occurrenceIds"], json!([expected_occurrence_id]));
    let expected_group_id = format!("{loop_plan_id}:g0:0/1");
    assert_eq!(loop_one["runtimeIds"]["groupIds"], json!([expected_group_id]),
        "groupId embeds the loop1 planId");

    // The `once` plan likewise propagates its own segment.
    assert!(none_plan["occurrences"][0]["occurrenceId"].as_str().expect("occurrenceId").starts_with(none_plan_id));
    assert_eq!(none_plan["runtimeIds"]["groupIds"], json!([format!("{none_plan_id}:g0:0/1")]));
}

#[test]
fn hand_scope_issues_are_reported_per_the_frozen_codes() {
    // A mapping that misses the part entirely -> hand_mapping_incomplete, and
    // the hand filter drops every occurrence (none mapped) -> empty groups.
    let events = json!([note_event("e1", 1, 1, "0/1", "1/1", 1, "1", 60, "C4")]);
    let mut config = config_for("left", 1, 1, json!({ "kind": "none" }), 3_000_000);
    config["handMapping"]["parts"] = json!([
        { "partId": "OTHER", "staves": [{ "staffNumber": 1, "hand": "left" }] }
    ]);
    let plan = build_plan_v1(&minimal_document(events.clone()), &minimal_report(), &config)
        .expect("unmapped plan still builds (fail-closed via emptiness)");
    assert_eq!(plan["scopeCodes"], json!(["hand_mapping_incomplete"]));
    assert_eq!(plan["missingEventIds"], json!(["e1"]));
    assert_eq!(plan["occurrences"].as_array().map(Vec::len), Some(0));
    // The plan built non-empty (both hands) so no_playable_notes was NOT
    // raised at build time; the hand filter does not append plan issues
    // (TS filterPlaybackPlanByHand keeps the plan's original issues).
    assert_eq!(plan["planStrictAllowed"], Value::Bool(true));

    // A multi-part document requires an explicit part selection. The second
    // part must be a VALID part (renamed ids): duplicate event ids would be
    // rejected by the a3 document validation before the planner runs.
    let mut multi = minimal_document(events);
    let mut second_part = multi["parts"][0].clone();
    second_part["partId"] = Value::String("P2".into());
    for event in second_part["measures"][0]["events"].as_array_mut().expect("events") {
        let renamed = format!("p2-{}", event["eventId"].as_str().expect("eventId"));
        event["eventId"] = Value::String(renamed);
        event["source"]["partId"] = Value::String("P2".into());
    }
    multi["parts"].as_array_mut().unwrap().push(second_part);
    let config = config_for("left", 1, 1, json!({ "kind": "none" }), 3_000_000);
    let plan = build_plan_v1(&multi, &minimal_report(), &config).expect("multi-part plan builds");
    assert_eq!(plan["scopeCodes"], json!(["multiple_parts_require_part_selection"]));
}

#[test]
fn inexact_tick_grid_blocks_the_atom_but_not_the_plan() {
    // A 1/7-beat group duration cannot live on the 960-ticks/quarter grid
    // (960/7 is not an integer; 1/3 would be exactly 320 ticks).
    let events = json!([note_event("e1", 1, 1, "0/1", "1/7", 1, "1", 60, "C4")]);
    let plan = build_plan_v1(&minimal_document(events), &minimal_report(), &base_config())
        .expect("non-grid plan still builds");
    assert_eq!(plan["atomIssueCodes"], json!(["tick_grid_rounding"]));
    assert_eq!(plan["atoms"].as_array().map(Vec::len), Some(0), "no rounded atom may appear");
    // The plan itself (occurrence/scoreEvent) survives on the exact domain.
    assert_eq!(plan["scoreEvents"][0]["targetDurationUs"], Value::from(107_143)); // 1/7 beat @80BPM, half-up
}

#[test]
fn empty_range_reports_no_playable_notes_and_the_gate_rejects_the_plan() {
    // A rest-only range builds an EMPTY plan; the fingerprint gate must
    // reject it with exactly the frozen payload error (TS EMPTY_PLAN path).
    let rest = json!([{
        "eventId": "r1", "kind": "rest",
        "source": { "partId": "P1", "measureOrdinal": 1, "staffNumber": 1, "sourceOrdinal": 1 },
        "onsetBeat": { "numerator": 0, "denominator": 1 },
        "durationBeat": { "numerator": 4, "denominator": 1 },
        "dots": 0,
        "tieStart": false, "tieStop": false, "tiedStart": false, "tiedStop": false,
        "isGrace": false, "isCue": false, "articulations": [],
    }]);
    let document = minimal_document(rest);
    let report = minimal_report();
    let config = base_config();
    let plan = build_plan_v1(&document, &report, &config).expect("empty plan builds");
    assert_eq!(plan["occurrences"].as_array().map(Vec::len), Some(0));
    assert_eq!(plan["planIssues"][0]["code"], Value::String("no_playable_notes".into()));
    assert_eq!(plan["planStrictAllowed"], Value::Bool(false));

    let error = plan_fingerprint_v1_gate(&document, &report, &plan, &config)
        .expect_err("empty plan cannot reach a fingerprint");
    assert_eq!(error.code, "PAYLOAD_VALIDATION_FAILED");
}
